mapper.select:
select `m`.`id`,`m`.`account`, `m`.`name`, `m`.`phone`, `m`.`email`, `m`.`status`, `m`.`create_time`, 
       `m`.`sex`, `m`.`avatar`
from sys_member as m


        `m`.`name` like concat("%",#{dto.name},"%")


        and `m`.`account` like concat("%",#{dto.account},"%")


        and `m`.`phone` like concat("%",#{dto.phone},"%")


        and `m`.`email` like concat("%",#{dto.email},"%")


        and `m`.`status`=#{dto.status}


        and `m`.`sex`=#{dto.sex}


        and `m`.`create_time` >= #{dto.beginTime}


        and `m`.`create_time` <= #{dto.endTime}

    and `m`.`deleted`=0

order by `m`.`create_time` desc
